#include "stdlib/lapack/base/dgbtf2.h"
#include "validate.h"
#include "panel.h"

/**
* Computes a band LU factorization using alternative indexing semantics.
*
* @param M          number of dense rows
* @param N          number of dense columns
* @param KL         number of subdiagonals
* @param KU         number of superdiagonals
* @param AB         compact band input/output
* @param strideAB1  band-row stride
* @param strideAB2  column stride
* @param offsetAB   first compact band cell
* @param PIV        positive one-based stepwise row interchanges
* @param stridePIV  pivot stride
* @param offsetPIV  first pivot cell
* @return           INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dgbtf2_ndarray)( const LAPACK_INT M, const LAPACK_INT N, const LAPACK_INT KL, const LAPACK_INT KU, double *AB, const LAPACK_INT strideAB1, const LAPACK_INT strideAB2, const LAPACK_INT offsetAB, LAPACK_INT *PIV, const LAPACK_INT stridePIV, const LAPACK_INT offsetPIV ) {
	dgbtf2_view ab;
	LAPACK_INT kv;
	LAPACK_INT h;
	LAPACK_INT k;
	LAPACK_INT info;
	intmax_t i;
	intmax_t j;
	intmax_t jp;
	intmax_t ju;
	intmax_t km;
	intmax_t end;

	info = dgbtf2_dimensions( 0, M, N, KL, KU, &kv, &h, &k );
	if ( info != 0 ) return dgbtf2_error( "c_dgbtf2_ndarray", info );
	info = dgbtf2_validate( 0, M, N, KL, KU, AB, strideAB1, strideAB2, offsetAB, PIV, stridePIV, offsetPIV );
	if ( info != 0 ) return dgbtf2_error( "c_dgbtf2_ndarray", info );
	if ( M == 0 || N == 0 ) return 0;
	ab.data = AB;
	ab.stride1 = strideAB1;
	ab.stride2 = strideAB2;
	ab.offset = offsetAB;

	// Set only the original initial fill-in footprint to positive zero.
	end = kv < N ? kv : N;
	for ( j = (intmax_t)KU+1; j < end; j++ ) {
		for ( i = kv-j; i < KL; i++ ) {
			DGBTF2_CELL( &ab, i, j ) = 0.0;
		}
	}
	ju = 1;
	for ( j = 0; j < k; j++ ) {
		if ( j+kv < N ) {
			for ( i = 0; i < KL; i++ ) {
				DGBTF2_CELL( &ab, i, j+kv ) = 0.0;
			}
		}
		km = KL < M-j-1 ? KL : M-j-1;
		jp = dgbtf2_first_absmax( km+1, &ab, kv, j );
		PIV[ (intmax_t)offsetPIV+j*stridePIV ] = (LAPACK_INT)(jp+j+1);
		if ( DGBTF2_CELL( &ab, kv+jp, j ) != 0.0 ) {
			end = j+KU+jp+1;
			if ( end > N ) end = N;
			if ( end > ju ) ju = end;
			if ( jp != 0 ) dgbtf2_swap( ju-j, &ab, kv+jp, kv, j );
			if ( km > 0 ) {
				dgbtf2_scale( km, 1.0/DGBTF2_CELL( &ab, kv, j ), &ab, kv+1, j );
				if ( ju > j+1 ) dgbtf2_ger( km, ju-j-1, &ab, kv, j );
			}
		} else if ( info == 0 ) {
			info = (LAPACK_INT)(j+1);
		}
	}
	return info;
}
